pub fn is_ascii_domain(domain: &str) -> bool {
    domain.is_ascii()
}

pub fn is_idn_domain(domain: &str) -> bool {
    !domain.is_ascii()
}

#[cfg(test)]
mod tests {
    use super::{is_ascii_domain, is_idn_domain};

    #[test]
    fn matches_observed_ascii_behavior() {
        assert!(is_ascii_domain(""));
        assert!(is_ascii_domain("example.com"));
        assert!(is_ascii_domain("foo bar.com"));
        assert!(!is_ascii_domain("例子.测试"));
        assert!(!is_ascii_domain("bücher.de"));
    }

    #[test]
    fn matches_observed_idn_behavior() {
        assert!(!is_idn_domain(""));
        assert!(!is_idn_domain("example.com"));
        assert!(is_idn_domain("例子.测试"));
        assert!(is_idn_domain("a例b.com"));
    }
}

