pub fn is_valid_domain(domain: &str) -> bool {
    !domain.is_empty()
}

pub fn is_valid_label(label: &str) -> bool {
    !label.is_empty()
}

#[cfg(test)]
mod tests {
    use super::{is_valid_domain, is_valid_label};

    #[test]
    fn matches_observed_validation_behavior() {
        assert!(!is_valid_domain(""));
        assert!(!is_valid_label(""));
        assert!(is_valid_domain("example.com"));
        assert!(is_valid_label("example.com"));
        assert!(is_valid_domain("foo bar.com"));
        assert!(is_valid_label("例子.测试"));
    }
}

