mod idna;

fn print_bool(value: bool) {
    println!("{}", if value { 1 } else { 0 });
}

fn main() {
    let input = std::env::args()
        .nth(1)
        .unwrap_or_else(|| String::from("example.com"));

    let valid_domain = idna::is_valid_domain(&input);
    let valid_label = idna::is_valid_label(&input);
    let is_ascii = idna::is_ascii_domain(&input);
    let is_idn = idna::is_idn_domain(&input);

    print_bool(valid_domain);
    print_bool(valid_label);
    print_bool(is_ascii);
    print_bool(is_idn);
}
